import sys


def main():
    deps = {}
    reverse_deps = {}
    for line in sys.stdin:
        if not line.strip():
            continue
        name, _, rest = line.partition(":")
        task = name.strip()
        deps.setdefault(task, []).extend(rest.split())

        # Populate the reverse dependencies map
        for d in rest.split():
            reverse_deps.setdefault(d, []).append(task)

    # Remove cycles from dependencies
    visited = set()
    cycle_found = False

    def dfs(task):
        nonlocal cycle_found
        if cycle_found:
            return
        if task in visited:
            return
        visited.add(task)
        for d in reverse_deps.get(task, []):
            dfs(d)
        visited.remove(task)

    for task in list(deps.keys()):
        if task not in visited:
            dfs(task)
            if task in visited:
                cycle_found = True
                break

    if cycle_found:
        remaining_tasks = sorted(deps.keys())
        print(f"CYCLE: {' '.join(remaining_tasks)}")
    else:
        done = set()
        order = []

        def visit(task):
            if task in done:
                return
            done.add(task)
            for d in sorted(deps.get(task, [])):
                visit(d)
            order.append(task)

        for task in sorted(deps.keys()):
            visit(task)
        for task in order:
            print(task)


if __name__ == "__main__":
    main()
